void stage(Key k, Row r) {
  { std::lock_guard lk(m_); dirty_[std::move(k)] = std::move(r); }
  cv_.notify_one();                     // one entry per key: coalesced
}
void run(std::stop_token st) {          // launched as std::jthread
  std::unique_lock lk(m_);
  while (cv_.wait(lk, st, [&]{ return !dirty_.empty(); })) {
    auto batch = std::exchange(dirty_, {});
    lk.unlock();
    flush(batch);                       // one transaction per batch
    lk.lock();
  }
}
